import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        int N = Integer.parseInt(tokenizer.nextToken());
        int k = Integer.parseInt(tokenizer.nextToken());
        List<int[]> intervals = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            tokenizer = new StringTokenizer(reader.readLine());
            intervals.add(new int[]{Integer.parseInt(tokenizer.nextToken()), Integer.parseInt(tokenizer.nextToken())});
        }
        intervals.add(new int[]{2 * N, 2 * N});
        int position = 0;
        SegmentTree[] dp = {new SegmentTree(N + 1), new SegmentTree(N + 1)};
        dp[0].assign(0, 0);
        for (int[] interval : intervals) {
            for (int j = N; j >= 0; j--) {
                dp[0].assign(j, dp[0].getVal(j - (interval[0] - position)));
            }
            position = interval[1];
            int length = interval[1] - interval[0];
            for (int j = N; j >= 0; j--) {
                int[] costs = new int[2];
                for (int z = 0; z <= 1; z++) {
                    int twoSwaps = dp[z].query(j - length, j);
                    int oneSwap = dp[(z + 1) % 2].query(j - length, j);
                    int noSwap;
                    if (z == 1) {
                        noSwap = dp[z].getVal(j);
                    } else {
                        noSwap = dp[z].getVal(j - length);
                    }
                    costs[z] = Math.min(twoSwaps + 2, Math.min(oneSwap + 1, noSwap));
                }
                dp[0].assign(j, costs[0]);
                dp[1].assign(j, costs[1]);
            }
        }
        int result = Math.min(dp[0].query(N, N), dp[1].query(N, N));
        if (result >= Integer.MAX_VALUE) {
            writer.println("Hungry");
        } else {
            writer.println("Full");
            writer.println(result);
        }
        writer.close();
    }

    static class SegmentTree {
        int[] tree;
        int[] data;
        int size;

        public SegmentTree(int N) {
            size = N;
            tree = new int[4 * N];
            data = new int[N];
            Arrays.fill(data, Integer.MAX_VALUE);
            Arrays.fill(tree, Integer.MAX_VALUE);
        }

        public int query(int l, int r) {
            if (r < 0) return Integer.MAX_VALUE;
            return queryRange(1, 0, size - 1, Math.max(0, l), r);
        }

        private int queryRange(int node, int start, int end, int l, int r) {
            if (l > r) return Integer.MAX_VALUE;
            if (l == start && r == end) return tree[node];
            int mid = (start + end) / 2;
            return Math.min(queryRange(node * 2, start, mid, l, Math.min(r, mid)),
                            queryRange(node * 2 + 1, mid + 1, end, Math.max(l, mid + 1), r));
        }

        public void assign(int index, int value) {
            data[index] = value;
            int node = 1, start = 0, end = size - 1;
            while (start != end) {
                int mid = (start + end) / 2;
                if (index <= mid) {
                    node = node * 2;
                    end = mid;
                } else {
                    node = node * 2 + 1;
                    start = mid + 1;
                }
            }
            tree[node] = value;
            node /= 2;
            while (node > 0) {
                tree[node] = Math.min(tree[node * 2], tree[node * 2 + 1]);
                node /= 2;
            }
        }

        public int getVal(int i) {
            if (i < 0 || i >= data.length) return Integer.MAX_VALUE;
            return data[i];
        }
    }
}
