#include <bits/stdc++.h>
using namespace std;

struct SegmentTree {
    vector<int> tree;
    vector<int> data;
    int size;

    SegmentTree(int N) {
        size = N;
        tree.assign(4 * N, INT_MAX);
        data.assign(N, INT_MAX);
    }

    int query(int l, int r) {
        if (r < 0) return INT_MAX;
        l = max(0, l);
        return queryRange(1, 0, size - 1, l, r);
    }

    int queryRange(int node, int start, int end, int l, int r) {
        if (l > r) return INT_MAX;
        if (l == start && r == end) return tree[node];
        int mid = (start + end) / 2;
        return min(queryRange(node * 2, start, mid, l, min(r, mid)),
                   queryRange(node * 2 + 1, mid + 1, end, max(l, mid + 1), r));
    }

    void assign(int index, int value) {
        data[index] = value;
        int node = 1, start = 0, end = size - 1;
        while (start != end) {
            int mid = (start + end) / 2;
            if (index <= mid) {
                node = node * 2;
                end = mid;
            } else {
                node = node * 2 + 1;
                start = mid + 1;
            }
        }
        tree[node] = value;
        node /= 2;
        while (node > 0) {
            tree[node] = min(tree[node * 2], tree[node * 2 + 1]);
            node /= 2;
        }
    }

    int getVal(int i) {
        if (i < 0 || i >= (int)data.size()) return INT_MAX;
        return data[i];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, k;
    cin >> N >> k;
    vector<vector<int>> intervals;
    for (int i = 0; i < k; i++) {
        int a, b;
        cin >> a >> b;
        intervals.push_back({a, b});
    }
    intervals.push_back({2 * N, 2 * N});
    int position = 0;
    SegmentTree dp[2] = {SegmentTree(N + 1), SegmentTree(N + 1)};
    dp[0].assign(0, 0);
    for (auto &interval : intervals) {
        for (int j = N; j >= 0; j--) {
            int val = dp[0].getVal(j - (interval[0] - position));
            dp[0].assign(j, val);
        }
        position = interval[1];
        int length = interval[1] - interval[0];
        for (int j = N; j >= 0; j--) {
            int costs[2];
            for (int z = 0; z <= 1; z++) {
                int twoSwaps = dp[z].query(j - length, j);
                int oneSwap = dp[(z + 1) % 2].query(j - length, j);
                int noSwap;
                if (z == 1) {
                    noSwap = dp[z].getVal(j);
                } else {
                    noSwap = dp[z].getVal(j - length);
                }
                costs[z] = min(twoSwaps + 2, min(oneSwap + 1, noSwap));
            }
            dp[0].assign(j, costs[0]);
            dp[1].assign(j, costs[1]);
        }
    }
    int result = min(dp[0].query(N, N), dp[1].query(N, N));
    if (result >= INT_MAX) {
        cout << "Hungry\n";
    } else {
        cout << "Full\n" << result << "\n";
    }
    return 0;
}

